using System;using System.Linq;using System.Reflection;using System.Globalization;using System.Windows.Forms;using BeamScheduleFormatter;
class BeamEarthworksTests {
 static int checks;static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}static void Near(double a,double b,string label){Check(Math.Abs(a-b)<1e-8,label+": "+a+" != "+b);}static void Reject(Action a,string label){bool rejected=false;try{a();}catch{rejected=true;}Check(rejected,label);}
 static object Field(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static BeamRow Manual(string mark){var r=new BeamRow{Mark=mark,Leg="2L",Diameter="O10",RevisedSpacing="1 - 50mm, AND REST AT 200mm C/C"};r.Spacing=r.RevisedSpacing;for(int n=0;n<14;n++)r.Cells[n].Add("-");r.Cells[0][0]="300";r.Cells[1][0]="500";for(int n=2;n<8;n++)r.Cells[n][0]="2-O16";r.Cells[5].Add("1-O20");return r;}
 [STAThread]static void Main(){
  var e=BeamEarthworks.Calculate(.3,.5,5,2,.6,.3,20,10,0);Near(e.Width,.9,"Allowance each side");Near(e.Excavation,5.4,"Bank excavation");Near(e.Gravel,.3,"100mm gravel under beam");Near(e.Concrete,1.5,"Concrete displacement");Near(e.Backfill,3.6,"Compacted backfill");Near(e.LooseExcavation,6.48,"Loose excavation");Near(e.LooseRequired,4.8,"Loose required");Near(e.LooseSurplus,1.68,"Loose surplus");Near(e.FromExcavation,e.Backfill,"Excavation supplies full backfill");Near(e.CommonBorrow,0,"No borrow if soil sufficient");Near(e.LooseFromExcavation,4.8,"Loose material reused excludes surplus");
  var deep=BeamEarthworks.Calculate(.3,.5,5,2,1.2,.3,20,10,.25);Near(deep.OtherConcrete,.5,"Lower tie volume multiplied");Near(deep.Backfill,8.5,"Deep trench minus both concretes and gravel");
  var deficit=BeamEarthworks.Calculate(.3,.5,5,1,.6,.3,20,80,0);Near(deficit.FromExcavation+deficit.CommonBorrow,deficit.Backfill,"Compacted source reconciliation");Near(deficit.CommonBorrow*1.2/.2,deficit.LooseImport,"Borrow delivery conversion");Near(deficit.LooseFromExcavation+deficit.LooseImport,deficit.LooseRequired,"Loose source reconciliation");Check(deficit.CommonBorrow>0,"Compacted deficit classified common borrow");Check(deficit.LooseImport>0&&deficit.LooseSurplus==0,"Deficit not clamped away");
  Reject(()=>BeamEarthworks.Calculate(.3,.5,5,1,.59,.3,20,10,0),"Too shallow");Reject(()=>BeamEarthworks.Calculate(.3,.5,5,1,.6,-.1,20,10,0),"Negative allowance");Reject(()=>BeamEarthworks.Calculate(.3,.5,5,1,.6,.3,20,100,0),"100 percent shrink");Reject(()=>BeamEarthworks.Calculate(.3,.5,5,1,.6,.3,double.NaN,10,0),"Nonfinite factor");Reject(()=>BeamEarthworks.Calculate(.3,.5,5,1,.6,0,20,10,1),"Impossible displacement");
  var a=new Analysis();a.Source.Add(Manual("TB-1"));string xml=ManualBeamSchedule.Serialize(a);var restored=ManualBeamSchedule.Read(xml,"Manual");Check(restored.Source[0].Cells[5].Count==2,"Layered bars survive save");Check(restored.Source[0].Cell(0)=="300","B preserved");
  using(var form=new EstimatorForm(null)){form.AddManual(a.Source[0]);Reject(()=>form.AddManual(Manual("TB-1")),"Duplicate manual mark rejected");form.AddManual(Manual("TB-2"));int n=form.AddEntry("Ground tie","TB-1","5","2");var grid=(DataGridView)Field(form,"beams");var row=grid.Rows[n];row.Cells[14].Value="Ground beam";form.Recalculate();var input=(EstimateInput)row.Tag;Near(input.Earthworks.Depth,.6,"Automatic D+gravel");Near(input.Earthworks.Excavation,5.4,"UI engine quantities");Check(!row.Cells[18].ReadOnly&&row.Cells[15].ReadOnly,"Context inputs");Check(row.Cells[19].ReadOnly,"Working allowance fixed");row.Cells[19].Value="0.80";form.Recalculate();Near(((EstimateInput)row.Tag).Earthworks.Allowance,.30,"Stored custom allowance normalized");row.Cells[18].Value="1.2";row.Cells[22].Value="0.25";form.Recalculate();Near(((EstimateInput)row.Tag).Earthworks.Backfill,8.5,"Per row override");string snapshot=form.WorksSnapshot();using(var opened=new EstimatorForm(null)){opened.WorksRestore(snapshot);var gr=(DataGridView)Field(opened,"beams");var i=(EstimateInput)gr.Rows[0].Tag;Near(i.Earthworks.Depth,1.2,"Depth persisted");Near(i.Earthworks.OtherConcrete,.5,"Tie displacement persisted");Check(i.Source.Cells[5].Count==2,"Manual layers restored in project");Check(opened.Report().Contains("GROUND BEAM EARTHWORKS"),"Report includes earthworks");Check(opened.EarthworkExcelRows().GetLength(0)==1,"Excel detail");Near(Convert.ToDouble(opened.EarthworkExcelRows()[0,16]),i.Earthworks.LooseFromExcavation,"Excel from excavation is loose");Near(Convert.ToDouble(opened.EarthworkExcelRows()[0,17]),i.Earthworks.LooseImport,"Excel common borrow is loose");Check(gr.Columns[30].HeaderText.Contains("loose")&&gr.Columns[31].HeaderText.Contains("loose"),"Final quantity headers state loose");}
   row.Cells[18].Value="bad";form.Recalculate();Check(((EstimateInput)row.Tag).Earthworks==null&&form.Report().Contains("PARTIAL EARTHWORKS"),"Invalid earthwork visible");Reject(()=>form.WorksExcelRows(),"Invalid earthworks block Excel sync");row.Cells[14].Value="Elevated slab";form.Recalculate();Check(((EstimateInput)row.Tag).Earthworks==null&&row.Cells[18].ReadOnly,"Elevated ignores retained earth inputs");
  }
  Console.WriteLine("PASS: "+checks+" beam earthwork/manual schedule checks.");
 }
}
